const j = $input.first().json;
const k = j.kind;
const nome = j.name ? ' ' + j.name : '';
const T = {
  signup: {
    subject: 'Sua conta MY TRAKR está pronta',
    lead:    'Falta um passo para começar: abra o link e receba sua chave de acesso.',
    cta:     'Criar minha conta',
    foot:    'O link vale 14 dias e serve uma vez só. A chave aparece uma única vez — tenha um gerenciador de senhas à mão.'
  },
  recover: {
    subject: 'Sua nova chave MY TRAKR',
    lead:    'Você pediu uma chave nova. Ao abrir o link, a chave anterior deixa de funcionar.',
    cta:     'Gerar chave nova',
    foot:    'O link vale 2 horas e serve uma vez só. Se não foi você quem pediu, ignore este e-mail — nada muda até alguém abrir o link.'
  },
  welcome: {
    subject: 'Bem-vindo ao MY TRAKR',
    lead:    'Sua conta está pronta. Abaixo está sua chave de acesso — guarde-a num gerenciador de senhas, ela não pode ser recuperada, apenas substituída.',
    cta:     'Abrir meu painel',
    foot:    'Para conectar sua IA: adicione um conector com a URL do MY TRAKR e cole a chave quando pedir. Conta gratuita do Claude já funciona.'
  },
  agency: {
    subject: 'Sua assessoria no MY TRAKR',
    lead:    'Sua assessoria está pronta para ser criada. Abra o link e receba a chave de dono.',
    cta:     'Criar minha assessoria',
    foot:    'O link vale 14 dias e serve uma vez só. A chave de dono aparece uma única vez.'
  }
}[k] ?? {};
return [{ json: { ...j, subject: T.subject, lead: T.lead, cta: T.cta, foot: T.foot, nome } }];

const j = $input.first().json;
const html = '<div style="font-family:system-ui,-apple-system,sans-serif;font-size:15px;line-height:1.6;color:#1a1c20;max-width:520px">' +
  '<p>Olá' + j.nome + ',</p>' +
  '<p>' + j.lead + '</p>' +
  '<p style="margin:26px 0"><a href="' + j.url + '" style="display:inline-block;background:' + j.accent + ';color:' + j.ink + ';font-weight:700;padding:13px 22px;border-radius:10px;text-decoration:none">' + j.cta + '</a></p>' +
  '<p style="color:#5b6070;font-size:13px">' + j.foot + '</p>' +
  '<p style="color:#5b6070;font-size:13px">Se o botão não funcionar, copie este endereço:<br><span style="word-break:break-all">' + j.url + '</span></p>' +
  '<hr style="border:0;border-top:1px solid #e4e6ea;margin:28px 0 14px">' +
  (j.signature || '<p style="color:#8b90a0;font-size:12px;margin:0"><strong>' + j.brand + '</strong></p>') +
  '</div>';
return [{ json: {
  from: j.brand + ' <' + $env.MAIL_FROM_ADDRESS + '>',
  to: [j.email],
  subject: j.subject,
  html,
} }];
